diff --git a/src/paginate.ts b/src/paginate.ts
index 0a1b2c3..a3b4c5d 100644
--- a/src/paginate.ts
+++ b/src/paginate.ts
@@ -8,3 +8,10 @@ export function slicePage<T>(items: T[], page: number, size = DEFAULT_PAGE_SIZE): T[] {
   const start = (page - 1) * size;
   return items.slice(start, start + size);
 }
+
+export type WithId = { id: string };
+
+export function nextCursor(items: WithId[], size = DEFAULT_PAGE_SIZE): string | null {
+  if (items.length <= size) return null;
+  return items[size - 1].id;
+}
